cases.source:
panel 3
node first { node a : std/literal }
node second { node b : std/literal }
root first
root second

panel 3
node router {
  node handler : fixture/handler
  port-group routes > : fixture/reply keyed max 3 { member home member assets }
  export home > = handler.routes[home]
}
port-group workers > : fixture/reply indexed max 8
root router

panel 3
node inner {
  node value : fixture/source
  export result > = value.result
}
node outer {
  node child : inner
  export result > = child.result
}
root outer

panel 3
pool rejectors : fixture/handler { maximum = 8 admission = reject deadline_ms = 1000 idle_timeout_ms = 5000 supervision = fail_together cleanup = abort }
pool blockers : fixture/handler { maximum = 8 admission = block deadline_ms = 1000 idle_timeout_ms = 5000 supervision = isolate cleanup = drain }
pool queued : fixture/handler { maximum = 8 admission = queue_bounded admission_queue = 32 deadline_ms = 1000 idle_timeout_ms = 5000 supervision = restart_bounded restart_attempts = 2 restart_backoff_ms = 50 cleanup = drain }
pool failed : fixture/handler { maximum = 8 admission = fail deadline_ms = 1000 idle_timeout_ms = 5000 supervision = fallback fallback = fixture/fallback cleanup = abort }

panel 3
node a : fixture/source
node b : fixture/sink
cord a.value -> b.value { capacity = 4 pressure = sample sample_every = 3 sample_offset = 1 }
cord a.value -> b.value { capacity = 4 pressure = coalesce coalescer = fixture/latest }
cord a.value -> b.value { capacity = 4 pressure = drop-disposable }

